import json

offset = 0
rolled = 0
while True:
    res = list_deployments(service='api', env='prod', status='failed', limit=100, offset=offset)
    items = res.get('items', [])
    for it in items:
        if not it.get('rolled_back'):
            r = rollback_deployment(it['id'])
            if r.get('ok'):
                rolled += 1
    total = res.get('total', 0)
    offset += len(items)
    if offset >= total or not items:
        break

print(json.dumps({'rolled_back': rolled}))

